'use client'

import { useQuery } from '@tanstack/react-query'

import { createBrowserClient } from '@/lib/supabase/client'

export interface ListPersona {
  username: string
  display_name: string
}

export const listPersonaKey = (personaId: string) => ['list-persona', personaId] as const

/**
 * The AI expert a list was generated as (`lists.ai_persona_id`), for its
 * "Generated by FieldScout AI as …" line (spec-ai-expert-personas.md, UI
 * requirement 4). The same read the public share page makes: an active,
 * undeleted persona — `null` when it is switched off or gone, where that page
 * shows no line either. Personas are anon-readable under RLS.
 */
export function useListPersona(personaId: string | null | undefined) {
  return useQuery({
    queryKey: listPersonaKey(personaId ?? ''),
    enabled: Boolean(personaId),
    staleTime: 10 * 60 * 1000,
    queryFn: async (): Promise<ListPersona | null> => {
      const { data, error } = await createBrowserClient()
        .from('ai_personas')
        .select('username, display_name')
        .eq('id', personaId as string)
        .eq('is_active', true)
        .is('deleted_at', null)
        .maybeSingle()
      if (error) throw error
      return (data as ListPersona | null) ?? null
    },
  })
}
